pub trait Summary {
    fn summarize(&self) -> String;
}

pub struct NewsArticle {
    pub headline: String,
    pub location: String,
    pub author: String,
}

impl Summary for NewsArticle {
    fn summarize(&self) -> String {
        format!("{}, by {} ({})", self.headline, self.author, self.location)
    }
}

pub struct SocialPost {
    pub username: String,
    pub content: String,
    pub reposts: u32,
}

impl Summary for SocialPost {
    fn summarize(&self) -> String {
        format!("{}: {}", self.username, self.content)
    }
}

fn main() {
    let post = SocialPost {
        username: String::from("horse_ebooks"),
        content: String::from("of course, as you probably already know, people"),
        reposts: 0,
    };
    let article = NewsArticle {
        headline: String::from("Penguins win the Stanley Cup Championship!"),
        location: String::from("Pittsburgh, PA, USA"),
        author: String::from("Iceburgh"),
    };
    println!("1 new post: {}", post.summarize());
    println!("New article: {}", article.summarize());
}

pub trait Summary {
    fn summarize_author(&self) -> String;

    fn summarize(&self) -> String {
        format!("(Read more from {}...)", self.summarize_author())
    }
}

pub struct SocialPost {
    pub username: String,
    pub content: String,
}

impl Summary for SocialPost {
    fn summarize_author(&self) -> String {
        format!("@{}", self.username)
    }
}

fn main() {
    let post = SocialPost {
        username: String::from("horse_ebooks"),
        content: String::from("of course"),
    };
    println!("1 new post: {}", post.summarize());
}

blocks.md:
The point of a trait is to write code that works with **any** type that has the behavior. There are several ways to say "a parameter of some type that implements `Summary`":

```rust
// impl Trait in argument position: short and clear
pub fn notify(item: &impl Summary) {
    println!("Breaking news! {}", item.summarize());
}

// the same thing as a trait bound on a generic parameter
pub fn notify<T: Summary>(item: &T) {
    println!("Breaking news! {}", item.summarize());
}
```

The long form is needed when two parameters must be the **same** type: `fn notify<T: Summary>(a: &T, b: &T)`. With `a: &impl Summary, b: &impl Summary` they may be different types.

