use std::fmt::{Debug, Display};

fn describe<T, U>(label: &T, value: &U) -> String
where
    T: Display,
    U: Debug + PartialOrd<U> + Default,
{
    let sign = if *value > U::default() { "above" } else { "not above" };
    format!("{label}: {value:?} is {sign} the default")
}

fn main() {
    println!("{}", describe(&"temperature", &21.5));
    println!("{}", describe(&String::from("count"), &0));
}

fn evens_up_to(n: u32) -> impl Iterator<Item = u32> {
    (0..=n).filter(|x| x % 2 == 0)
}

fn main() {
    let v: Vec<u32> = evens_up_to(10).collect();
    println!("{v:?}");
}

