trait Shout {
    fn shout(&self) -> String;
}

// every type that can be displayed can now shout
impl<T: std::fmt::Display> Shout for T {
    fn shout(&self) -> String {
        self.to_string().to_uppercase() + "!"
    }
}

fn main() {
    println!("{}", "hello".shout());
    println!("{}", 42.shout());
    println!("{}", 'x'.shout());
}

struct Countdown {
    n: u32,
}

impl Iterator for Countdown {
    type Item = u32;

    fn next(&mut self) -> Option<Self::Item> {
        if self.n == 0 {
            None
        } else {
            self.n -= 1;
            Some(self.n + 1)
        }
    }
}

fn main() {
    for x in (Countdown { n: 3 }) {
        print!("{x} ");
    }
    println!("liftoff");
    let total: u32 = Countdown { n: 4 }.sum();
    println!("{total}");
}

